-- Demo seed: a fictional store, generated by data/seed_generator.py.
-- No real customer, pricing or contractor data appears in this repository.
--
-- Dates are relative to CURRENT_DATE so the ageing and credit scenarios stay
-- true whenever this migration runs.



-- Catalogue: 223 lines a small hardware store would actually carry,
-- including items with no barcode and items sold by the metre or kilogram.
SELECT setval('product_id_seq', (SELECT max(id) FROM product));

-- Opening stock count. Historic sales below are seeded as financial
-- history only, so they do not draw this count down.

SELECT setval('contractor_account_id_seq', (SELECT max(id) FROM contractor_account));

-- Buyers authorised to charge to an account. PINs are BCrypt hashed; the
-- demo PIN for every buyer is listed in the README.
SELECT setval('authorised_buyer_id_seq', (SELECT max(id) FROM authorised_buyer));

SELECT setval('job_site_id_seq', (SELECT max(id) FROM job_site));

-- Account sales. Each one is a tax invoice: trade-priced, tagged to a job,
-- signed for by the buyer who collected, and due on the account's terms.
-- Walk-in sales, one row per transaction, rebuilt from 90 days of daily totals.
SELECT setval('sale_id_seq', (SELECT max(id) FROM sale));



-- Payments received against accounts, allocated oldest invoice first,
-- exactly as PaymentAllocationService does at runtime.
SELECT setval('account_payment_id_seq', (SELECT max(id) FROM account_payment));


-- Carry on numbering where the seeded documents left off.
